// Hand-derived minimal type surface of @cancjs/lazy-promise for fixtures.
// LazyPromise is a lazy thenable, detected separately from CancelablePromise (it is NOT nominally
// a CancelablePromise even though it is cancelable and promise-like).

import { ICancelablePromiseOptions } from '@cancjs/promise';

export interface ILazyPromiseOptions extends ICancelablePromiseOptions {
 resettable?: boolean;
}

export type TLazyExecutor<T> = (
 resolve: (value?: T | PromiseLike<T>) => void,
 reject: (reason?: any) => void,
) => void | (() => void);

export declare class LazyPromise<T = any> implements PromiseLike<T> {
 constructor(executor: TLazyExecutor<T>, options?: ILazyPromiseOptions);
 then<TResult1 = T, TResult2 = never>(
 onFulfilled?: ((value: T) => TResult1 | PromiseLike<TResult1>) | null,
 onRejected?: ((reason: any) => TResult2 | PromiseLike<TResult2>) | null,
 ): PromiseLike<TResult1 | TResult2>;
 cancel(reason?: any): void;
}

export declare class NativeLazyPromise<T = any> extends LazyPromise<T> {}

export declare function lazy<T = any>(
 executor: TLazyExecutor<T>,
 options?: ILazyPromiseOptions,
): LazyPromise<T>;

export default lazy;
